   counts=marker_counts(pl)
   if all(len(ns)>=2 for ns in counts.values()):
    key=tuple((n,pl[n]) for n in sorted(pl))
    results.add(key)
   return
  # calculate all candidate options for each remaining piece, sorted by # overlaps descending
  options_by={}
  marks_existing=set().union(*(shifted(marker_groups[n],*off) for n,off in pl.items()))
  for n in left:
   poss=set()
   for m in marker_groups[n]:
    for p0 in marks_existing:
     poss.add((p0[0]-m[0],p0[1]-m[1]))
   opts=[]
   for off in poss:
    trial={**pl,n:off}
    if valid_full_conflict(trial): continue
    mset=shifted(marker_groups[n],*off)
    ov=mset&marks_existing
    if ov:
     opts.append((len(ov),off,ov))
   opts.sort(key=lambda x:(-x[0],x[1]))
   options_by[n]=opts
  # Pick piece with fewest options (>0); any connected solution can choose any order but only connectable now
  possible=[(len(options_by[n]),n) for n in left if options_by[n]]
  if not possible: return
  _,n=min(possible)
  # But choosing most constrained component may exclude solutions if it isn't next in spanning order while another can attach first.
